INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 3, 'theory', 'The Data Link Layer: Ethernet, MAC Addresses, Switches, and Wi-Fi');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 3, 0, 'What does a switch do when it receives a frame with an unknown destination MAC address?', '["Drops it", "Sends copies to all the other ports", "Sends it to the nearest port", "Replies to the sender with an error"]', 1, 'This is flooding: until the address is learned, the frame goes to every port except the one it came in on.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 3, 1, 'How does a switch fill its MAC address table?', '["It remembers the destination MACs", "It takes addresses from the administrator''s settings", "It remembers the sender''s MAC and the port the frame came in on", "It asks the router for addresses"]', 2, 'The source of the data is the "source MAC" field in incoming frames.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 3, 2, 'Why is a loop in a network of switches dangerous?', '["Broadcast frames circle forever: a storm", "Frames travel too slowly", "The MAC table gets cleared", "Link speed drops by half"]', 0, 'Broadcast frames multiply and the network chokes; STP protects against this.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 3, 3, 'What does a trunk between two switches do?', '["Increases the cable''s speed", "Merges all VLANs into one", "Encrypts the traffic", "Carries frames of several VLANs over one cable, tagging them with the VLAN number"]', 3, 'On a trunk, every frame gets an 802.1Q tag with the VLAN number.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 3, 4, 'Why does Wi-Fi use collision avoidance instead of collision detection?', '["Wi-Fi always works in full duplex", "A device can''t hear others while it transmits", "There are no collisions on the radio air", "It is faster for large files"]', 1, 'Its own signal drowns out the others, so it waits for a free channel and acknowledges frames.');
